"""Preserve the inspected T2S administration business model and scoped role records."""
from pathlib import Path
import json,sys
sys.path.insert(0,str(Path(__file__).resolve().parent))
from extract_workbooks import fm,write,relative,original_links
ROOT=Path(__file__).resolve().parents[1];JOB='job-000001'
source=next(s for s in json.loads((ROOT/'catalog/sources.json').read_text('utf-8'))['sources'] if s['source_id']=='src-000345')
results=json.loads((ROOT/'work/workbook-results.json').read_text('utf-8'));result=next(s for s in results if s['source_id']=='src-000345');diagram=next(d for d in result['diagrams'] if d['sheet']=='AdminFunction')
page=ROOT/diagram['page'];base=Path(source['set_path'])/'workbooks/src-000345'
entities=json.loads((ROOT/'work/workbook-diagrams/admin-function-entities.json').read_text('utf-8'))
code=(ROOT/'work/workbook-diagrams/admin-function.mmd').read_text('utf-8')
datatypes={'GenericIdentification','Scheme','DateTimePeriod','CashClearingSystemMember'}
roledata=[
('information-party-role','InformationPartyRole','Role played by a party as source of information.','Information source for a generic identification or a scheme. The subtype IdentificationIssuerRole identifies an entity assigning an identification.','A141:F148','identification-issuer-role','Parent of IdentificationIssuerRole; links GenericIdentification and Scheme.'),
('identification-issuer-role','IdentificationIssuerRole','Entity that assigns the identification.','Assigns an identification. This is a source-defined business role; the model does not require that its player be a particular institution.','A148:F148','information-party-role','Specializes InformationPartyRole.'),
('system-party-role','SystemPartyRole','Role played by a party in a system.','Relates a party role to the system for which the role is played. It is a context-dependent business role.','A1700:F1701','clearing-member-role','Parent of ClearingMemberRole; related to System.'),
('clearing-member-role','ClearingMemberRole',"Member of an exchange's clearing corporation, responsible for executing client trades and involved in the clearing of trades.",'Executes client trades and participates in clearing. The default-fund-account relationship points to an account at an ICSD or central bank. Clearing-system-member identification is assigned by the system or administrator.','A1708:F1714','system-party-role','Specializes SystemPartyRole; links Account through DefaultFundAccount/DefaultFundAccountOwner and CashClearingSystemMember through clearing-member identification.')
]
for suffix,label,definition,responsibility,ran,other,relationships in roledata:
 rid='t2s-administration-'+suffix;pg=ROOT/'shared/reference/participants'/(rid+'.md')
 body=fm(document_kind='participant',participant_id=rid,domain='shared',aliases=[label],source_ids=['src-000345'],source_locations=['FullBusinessModel!'+ran,'AdminFunction; '+diagram['drawing_part']+' anchor '+str(diagram['anchor_id'])],message_sets=['t2s-administration'],message_ids=[],flows=[],limitations=['The conceptual model does not establish the sender/receiver of an individual administrative message.'],curated=True)
 body+='# '+label+' — T2S administration model\n\n## Definition and context\n\n'+definition+'\n\nThis canonical record is scoped to the supplied T2S administration business model. It is not merged with identically labelled roles in other contexts merely by name.\n\n## Responsibilities and relationships\n\n'+responsibility+'\n\n'+relationships+' See ['+other+']('+relative(pg,ROOT/'shared/reference/participants'/('t2s-administration-'+other+'.md'))+').\n\n## Identifiers and applicability\n\nThe role is a BusinessComponent in the conceptual model, not itself an identifier datatype or named institution. Identification schemes and related identifiers must be read from their linked model components; no universal role identifier scheme is inferred. This model belongs to T2S Administration. It does not by itself allocate an initiating, receiving or acting role to each exact administrative message, or define an ordered business flow.\n\n## Provenance and review\n\n'+original_links(ROOT,source,pg)+'; src-000345, FullBusinessModel!'+ran+'; AdminFunction '+diagram['drawing_part']+' anchor '+str(diagram['anchor_id'])+'. The [source reconstruction]('+relative(pg,page)+') preserves the conceptual relationships. Definitions were read from the cited worksheet cells; the model was visually compared with the original. Cross-process role equivalence and per-message actor mappings remain needs-review.\n'
 write(ROOT,pg,body,JOB)
loc='AdminFunction; '+diagram['drawing_part']+' anchor '+str(diagram['anchor_id'])+'; '+diagram.get('from_cell','absolute')
body=fm(document_kind='diagram',domain='shared',diagram_id=diagram['figure_id'],diagram_kind='classDiagram',origin='source-reconstruction',source_ids=['src-000345'],source_locations=[loc],review_status='reviewed',curated=True,renderer='Mermaid 12.3.0; Chromium 156.0.8078.81',render_result='pass',visual_review='2026-11-08; source and rendered PNG compared for all 17 entities, 13 associations, 6 inheritance arrows, role labels and package labels.',participants=['t2s-administration-'+r[0] for r in roledata],limitations=['Source association-end labels are carried as edge labels and transcribed in the table; geometric label placement is not preserved.','The source artwork shows no association multiplicities; none are invented.'])
body+='# T2S administration conceptual model\n\nSource: '+original_links(ROOT,source,page)+'; src-000345, '+loc+'. Original picture bytes and drawing anchors are preserved.\n\n![Original source model]('+relative(page,ROOT/diagram['asset'])+')\n\n## Mermaid reconstruction\n\n'+chr(96)*3+'mermaid\n'+code+chr(96)*3+'\n\n## Entities and source packages\n\n| BusinessComponent | Source package label |\n| --- | --- |\n'
for c in entities['classes']:body+='| '+c+' | from '+('DICO_BusinessComponentsDataTypes' if c in datatypes else 'DICO_BusinessComponents')+' |\n'
body+='\n## Complete relationship transcription\n\nPlain associations below are undirected source lines; a label is a source relationship-end label, not an invented message direction. Plus/minus prefixes are retained as printed. The artwork does not display cardinality values. Inheritance points from subtype to parent; it does not establish an institution hierarchy or database ownership.\n\n| Endpoint / parent | Relationship | Endpoint / subtype | Printed relationship labels |\n| --- | --- | --- | --- |\n'
for a,e,b,label in entities['edges']:body+='| '+a+' | '+('generalization; hollow triangle at parent' if e=='<|--' else 'association')+' | '+b+' | '+(label or 'no label visible')+' |\n'
body+='\nThe FullBusinessModel rows 141–167, 476–495, 521–560, 585–592, 678–739, 1288–1307, 1664–1714 and 1792–1793 corroborate the named concepts and associated relationship endpoints. This reconstruction includes only the relationships drawn in AdminFunction, not every relationship in the full dictionary. In particular, additional dictionary relations are not silently added to the source artwork.\n\n## Scoped participants\n\n'
for suffix,label,*rest in roledata:body+='- ['+label+']('+relative(page,ROOT/'shared/reference/participants'/('t2s-administration-'+suffix+'.md'))+').\n'
body+='\nThis is a conceptual model, not an activity or message-exchange flow. It does not identify initiators, message senders, receivers, or business-process outcomes. Diagram-tool navigation icons are interface ornaments and are not reconstructed as semantic edges.\n\n## Rendering and visual review\n\nMermaid 12.3.0 parsed and rendered this class diagram using Chromium 156.0.8078.81 on 2026-11-08. The source PNG and final rendered PNG were opened and compared. All 17 entities, all six generalization directions, all 13 plain associations, visible source role labels and all package labels are accounted for. Layout and source label placement differ; the complete relationship table preserves the interpretation.\n\n[Rendered PNG]('+relative(page,ROOT/'shared/assets/src-000345/reconstructed/admin-function.png')+'), [SVG]('+relative(page,ROOT/'shared/assets/src-000345/reconstructed/admin-function.svg')+'), [render report]('+relative(page,ROOT/'work/workbook-admin-render-report.json')+'). The review covers this figure; it does not mark the entire workbook reviewed.\n'
write(ROOT,page,body,JOB)
diagram.update(disposition='converted',review_status='reviewed',render_evidence='work/workbook-admin-render-report.json',visual_review='2026-11-08; all source entities, edges, inheritance, labels and packages visually compared.')
mp=ROOT/'work/workbooks/src-000345/workbook.json';m=json.loads(mp.read_text('utf-8'))
for sh in m['sheets']:
 for d in sh['drawings']:
  if d['page']==diagram['page']:d.update({k:diagram[k] for k in ['disposition','review_status','render_evidence','visual_review']})
write(ROOT,mp,json.dumps(m,ensure_ascii=False,indent=2),JOB)
write(ROOT,ROOT/'work/workbook-results.json',json.dumps(results,ensure_ascii=False,indent=2),JOB)
print('Administrative model reconstructed/reviewed; four scoped participant records created.')
